"use strict";const COOKIE_BAR_RETRY_DELAYS_MS=[6e3,61e3];function startCookieBar(o,n){let e=0;const t=()=>Promise.resolve().then(()=>o(n)).catch(r=>{if(e<COOKIE_BAR_RETRY_DELAYS_MS.length){const s=COOKIE_BAR_RETRY_DELAYS_MS[e];return e+=1,new Promise(i=>{window.setTimeout(()=>i(t()),s)})}console.warn("Cookie consent status could not be loaded.",r)});return t()}window.startCookieBar=startCookieBar;
